// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 v1, uint256 v2, address actor, uint256 t) public {
        vm.assume(v1 <= VALUE_CAP);
        vm.assume(v2 <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(v1 <= type(uint256).max - v2);
        v1 = bound(v1, 0, 10 ether);
        v2 = bound(v2, 0, 10 ether);
        t = bound(t, 2, type(uint256).max - 1);

        vm.warp(t - 1);
        vm.deal(actor, v1);
        vm.prank(actor);
        c.Put{value: v1}(0);

        vm.warp(t);
        vm.deal(actor, v2);
        vm.prank(actor);
        c.Put{value: v2}(0);

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == v1 + v2, "balance must accumulate all deposits");
    }
}
